CREATE TABLE IF NOT EXISTS projects(id text PRIMARY KEY,name text NOT NULL,created_by text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_tenant_updated_idx ON projects(tenant_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS project_members(project_id text NOT NULL REFERENCES projects(id) ON DELETE CASCADE,actor_id text NOT NULL,tenant_id text NOT NULL REFERENCES tenants(id),role text NOT NULL DEFAULT 'EDITOR',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,actor_id));
CREATE TABLE IF NOT EXISTS security_token_revocations(jti text PRIMARY KEY,tenant_id text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_replay_keys(scope text NOT NULL,replay_key text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,replay_key));
CREATE TABLE IF NOT EXISTS episodes(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,channel_id text,title text NOT NULL,description text NOT NULL DEFAULT '',state text NOT NULL DEFAULT 'DRAFT',revision bigint NOT NULL DEFAULT 1,current_versions jsonb NOT NULL DEFAULT '{}'::jsonb,current_render_id text,approved_render_id text,published_record_id text,created_by text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS episodes_project_updated_idx ON episodes(project_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS version_records(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),kind text NOT NULL,parent_id text REFERENCES version_records(id),payload jsonb NOT NULL DEFAULT '{}'::jsonb,content_hash text,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(episode_id,id));
CREATE TABLE IF NOT EXISTS version_dependencies(episode_id text NOT NULL REFERENCES episodes(id),version_id text NOT NULL REFERENCES version_records(id),depends_on_version_id text NOT NULL REFERENCES version_records(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(version_id,depends_on_version_id));
CREATE TABLE IF NOT EXISTS artifacts(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),kind text NOT NULL,version_id text NOT NULL REFERENCES version_records(id),storage_uri text,content_json jsonb,content_hash char(64),media_type text,provider_run_id text,source text NOT NULL DEFAULT 'forge',license jsonb,input_version_ids jsonb NOT NULL DEFAULT '[]'::jsonb,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(storage_uri IS NOT NULL OR content_json IS NOT NULL));
CREATE INDEX IF NOT EXISTS artifacts_episode_created_idx ON artifacts(episode_id,created_at DESC);
CREATE TABLE IF NOT EXISTS provider_runs(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),capability text NOT NULL,provider text NOT NULL,model text,input_version_ids jsonb NOT NULL DEFAULT '[]'::jsonb,idempotency_key text NOT NULL UNIQUE,request jsonb NOT NULL DEFAULT '{}'::jsonb,attempt integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'QUEUED',external_job_id text,result_artifact_ids jsonb NOT NULL DEFAULT '[]'::jsonb,usage jsonb NOT NULL DEFAULT '{}'::jsonb,estimated_cost numeric(20,8),actual_cost numeric(20,8),currency char(3) NOT NULL DEFAULT 'USD',error jsonb,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,finished_at timestamptz);
CREATE TABLE IF NOT EXISTS cost_records(id text PRIMARY KEY,provider_run_id text NOT NULL REFERENCES provider_runs(id),episode_id text NOT NULL REFERENCES episodes(id),provider text NOT NULL,model text,operation text NOT NULL,input_units numeric(24,6) NOT NULL DEFAULT 0,output_units numeric(24,6) NOT NULL DEFAULT 0,estimated_cost numeric(20,8),actual_cost numeric(20,8),currency char(3) NOT NULL DEFAULT 'USD',is_retry boolean NOT NULL DEFAULT false,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS qa_results(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),artifact_id text NOT NULL REFERENCES artifacts(id),version_id text NOT NULL REFERENCES version_records(id),status text NOT NULL,checks jsonb NOT NULL DEFAULT '[]'::jsonb,runner text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,idempotency_key text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approvals(id text PRIMARY KEY,episode_id text NOT NULL REFERENCES episodes(id),stage text NOT NULL,target_id text NOT NULL,target_version_id text NOT NULL,decision text NOT NULL,actor text NOT NULL,comments text NOT NULL DEFAULT '',evidence jsonb NOT NULL DEFAULT '{}'::jsonb,decided_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS approvals_approved_idx ON approvals(episode_id,stage,target_id,target_version_id) WHERE decision='APPROVED';
CREATE TABLE IF NOT EXISTS audit_events(id bigserial PRIMARY KEY,project_id text REFERENCES projects(id),episode_id text REFERENCES episodes(id),actor text NOT NULL,action text NOT NULL,target_type text NOT NULL,target_id text NOT NULL,request_id text,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
